CREATE TYPE "AssetType" AS ENUM ('VEHICLE','EQUIPMENT','FURNITURE','COMPUTER','TOOL','OTHER'); CREATE TYPE "AssetStatus" AS ENUM ('ACTIVE','ASSIGNED','UNDER_MAINTENANCE','RETIRED','DISPOSED'); CREATE TYPE "DepreciationMethod" AS ENUM ('NONE','STRAIGHT_LINE','WRITTEN_DOWN_VALUE');
CREATE TABLE "assets" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"companyId" UUID NOT NULL,"branchId" UUID NOT NULL,"assetNumber" VARCHAR(100) NOT NULL,"name" VARCHAR(240) NOT NULL,"assetType" "AssetType" NOT NULL,"category" VARCHAR(120),"purchaseDate" DATE NOT NULL,"purchaseValue" DECIMAL(18,2) NOT NULL,"vendorId" UUID,"purchaseDocumentId" UUID,"purchaseDocumentLineId" UUID,"description" TEXT,"serialNumber" VARCHAR(160),"registrationNumber" VARCHAR(80),"makeModel" VARCHAR(160),"manufactureYear" INTEGER,"status" "AssetStatus" NOT NULL DEFAULT 'ACTIVE',"assignedUserId" UUID,"location" VARCHAR(240),"depreciationMethod" "DepreciationMethod" NOT NULL DEFAULT 'NONE',"usefulLifeMonths" INTEGER,"salvageValue" DECIMAL(18,2) NOT NULL DEFAULT 0,"depreciationStartDate" DATE,"assetLedgerId" UUID,"accumulatedDepreciationLedgerId" UUID,"depreciationExpenseLedgerId" UUID,"createdById" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL); CREATE UNIQUE INDEX "assets_companyId_id_key" ON "assets"("companyId","id"); CREATE UNIQUE INDEX "assets_companyId_assetNumber_key" ON "assets"("companyId","assetNumber"); CREATE INDEX "assets_scope_idx" ON "assets"("companyId","branchId","status"); ALTER TABLE "assets" ADD CONSTRAINT "assets_branch_fk" FOREIGN KEY ("companyId","branchId") REFERENCES "branches"("companyId","id") ON DELETE RESTRICT; ALTER TABLE "assets" ADD CONSTRAINT "assets_vendor_fk" FOREIGN KEY ("companyId","vendorId") REFERENCES "vendors"("companyId","id") ON DELETE RESTRICT;
CREATE TABLE "asset_assignment_history" ("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"companyId" UUID NOT NULL,"assetId" UUID NOT NULL,"assignedToId" UUID NOT NULL,"assignedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"returnedAt" TIMESTAMP(3),"assignedById" UUID NOT NULL,"notes" TEXT); CREATE UNIQUE INDEX "asset_assignment_companyId_id_key" ON "asset_assignment_history"("companyId","id"); CREATE INDEX "asset_assignment_history_idx" ON "asset_assignment_history"("companyId","assetId","assignedAt"); ALTER TABLE "asset_assignment_history" ADD CONSTRAINT "asset_assignment_asset_fk" FOREIGN KEY ("companyId","assetId") REFERENCES "assets"("companyId","id") ON DELETE RESTRICT;
